import axios from 'axios';

export async function refreshToken() {
    await axios.post('/tokenServer')
        .then(res => {
            const accessToken = res.data.token;
            localStorage.setItem('authToken', accessToken);
            return accessToken
        })
        .catch(err => {
            console.error('Error refreshing token:', err);
        });
}

export function isTokenExpired() {
    const token = localStorage.getItem('authToken');
    if (!token || token.split('.').length !== 3) return true;

    try {
        const decodedToken = JSON.parse(atob(token.split('.')[1]));
        return decodedToken.exp < Date.now() / 1000;
    } catch (e) {
        console.error('Error decoding token:', e);
        return true;
    }
}

export async function checkState(token, navigate) {
    try {
        const res = await axios.post('/checkAdminServer', { token });
        const isAdmin = (res.data == 1 || res.data == 2);

        if (isAdmin) {
            navigate('/admin');
        } else {
            navigate('/learn');
        }

        return isAdmin;
    } catch (err) {
        console.error('Error checking admin state:', err);
        return null;
    }
}
